import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
  spring,
  Sequence,
  Easing,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

const { fontFamily: interFamily } = loadInter();



export type LinkedInChatProps = Record<string, any>;

const LinkedInChat: React.FC<LinkedInChatProps> = ({
  backgroundColor = "#ffffff",
  transparentBackground = false,
  durationInSeconds = 8,
  recipientName = "Malloy Studio",
  messageText = "I'd love to come to this padel event!",
  themeColor = "#0a66c2",
  typingSpeed = 2,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Parser safety for transparent backgrounds
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Animation Timings
  const introDuration = 20;
  const typingStart = introDuration + 10;
  const typingDuration = messageText.length * typingSpeed;
  const typingEnd = typingStart + typingDuration;

  const tapStart = typingEnd + Math.floor(fps * 0.5); // 0.5s pause before hitting send
  const bubbleStart = tapStart + 10; // Bubble flies right after tap

  // Typing Logic
  const charsVisible = Math.max(
    0,
    Math.min(
      messageText.length,
      Math.floor((frame - typingStart) / typingSpeed)
    )
  );
  const currentDisplayedText = messageText.substring(0, charsVisible);
  const isTypingDone = charsVisible === messageText.length;

  // Blinking Cursor Logic
  const cursorVisible =
    frame < bubbleStart &&
    (frame < typingStart || isTypingDone
      ? frame % fps < fps / 2 // Blink before typing starts and after finished
      : true); // Solid while typing

  // Send Button Animation
  const tapScale = interpolate(
    frame,
    [tapStart, tapStart + 4, tapStart + 10],
    [1, 0.85, 1],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );
  
  const sendButtonActive = charsVisible > 0;
  const sendButtonOpacity = sendButtonActive ? 1 : 0.4;
  const finalSendOpacity = frame >= bubbleStart ? 0.4 : sendButtonOpacity;

  // Input Box State
  const inputTextVisible = frame < bubbleStart ? currentDisplayedText : "";
  const cursorOpacity = cursorVisible && frame < bubbleStart ? 1 : 0;

  // Message Bubble Animation (Sent)
  const bubbleSpring = spring({
    fps,
    frame: frame - bubbleStart,
    config: { damping: 14, stiffness: 120 },
  });

  const bubbleY = interpolate(bubbleSpring, [0, 1], [300, 0]);
  const bubbleScale = interpolate(bubbleSpring, [0, 1], [0.4, 1]);
  const bubbleOpacity = interpolate(bubbleSpring, [0, 0.8], [0, 1]);

  // Overall App Intro Fade
  const appOpacity = interpolate(frame, [0, introDuration], [0, 1], {
    extrapolateRight: "clamp",
  });
  const appY = interpolate(frame, [0, introDuration], [50, 0], {
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.cubic),
  });

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: interFamily,
        justifyContent: "center",
        alignItems: "center",
        transition: "none",
      }}
    >
      <div
        style={{
          width: width,
          height: height,
          display: "flex",
          flexDirection: "column",
          opacity: appOpacity,
          transform: `translateY(${appY}px)`,
          transition: "none",
        }}
      >
        {/* Top Header */}
        <div
          style={{
            height: height * 0.12,
            width: "100%",
            display: "flex",
            flexDirection: "row",
            alignItems: "center",
            padding: "0 40px",
            paddingTop: height * 0.04, // Safe zone adjustment
            borderBottom: "2px solid #ebebeb",
            backgroundColor: "#ffffff",
            zIndex: 10,
          }}
        >
          {/* Back Arrow Mock */}
          <div
            style={{
              width: 40,
              height: 40,
              borderTop: "6px solid #666",
              borderLeft: "6px solid #666",
              transform: "rotate(-45deg)",
              marginRight: 40,
            }}
          />
          {/* Avatar */}
          <div
            style={{
              width: 80,
              height: 80,
              borderRadius: "50%",
              backgroundColor: "#d9e2ec",
              marginRight: 30,
              overflow: "hidden",
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
            }}
          >
            <div
              style={{
                width: 40,
                height: 40,
                borderRadius: "50%",
                backgroundColor: "#bcccdc",
                transform: "translateY(-10px)",
              }}
            />
            <div
              style={{
                width: 70,
                height: 50,
                borderRadius: "35px 35px 0 0",
                backgroundColor: "#bcccdc",
                position: "absolute",
                bottom: 0,
              }}
            />
          </div>
          {/* Name & Status */}
          <div style={{ display: "flex", flexDirection: "column" }}>
            <span
              style={{
                fontSize: 42,
                fontWeight: 600,
                color: "#191919",
                letterSpacing: "-0.5px",
              }}
            >
              {recipientName}
            </span>
            <span
              style={{
                fontSize: 28,
                color: "#666666",
                marginTop: 4,
              }}
            >
              Active now
            </span>
          </div>
        </div>

        {/* Chat History Area */}
        <div
          style={{
            flex: 1,
            backgroundColor: "#ffffff",
            display: "flex",
            flexDirection: "column",
            justifyContent: "flex-end",
            padding: "40px",
            paddingBottom: 20,
            position: "relative",
          }}
        >
          {/* Sent Message Bubble */}
          <div
            style={{
              alignSelf: "flex-end",
              maxWidth: "80%",
              backgroundColor: themeColor,
              padding: "30px 40px",
              borderRadius: "40px 40px 10px 40px",
              opacity: bubbleOpacity,
              transform: `translateY(${bubbleY}px) scale(${bubbleScale})`,
              transformOrigin: "bottom right",
              boxShadow: "0 10px 30px rgba(0,0,0,0.08)",
              transition: "none",
            }}
          >
            <span
              style={{
                fontSize: 40,
                color: "#ffffff",
                lineHeight: 1.4,
                fontWeight: 400,
              }}
            >
              {messageText}
            </span>
          </div>
        </div>

        {/* Bottom Input Area */}
        <div
          style={{
            height: height * 0.12,
            minHeight: 180,
            width: "100%",
            display: "flex",
            flexDirection: "row",
            alignItems: "center",
            padding: "0 40px",
            paddingBottom: height * 0.03, // Safe zone adjustment for bottom edge
            backgroundColor: "#ffffff",
            borderTop: "2px solid #ebebeb",
            zIndex: 10,
          }}
        >
          {/* Plus Icon Mock */}
          <div
            style={{
              width: 50,
              height: 50,
              borderRadius: "50%",
              backgroundColor: "#666666",
              position: "relative",
              marginRight: 30,
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
            }}
          >
            <div style={{ width: 20, height: 4, backgroundColor: "#fff", position: "absolute" }} />
            <div style={{ width: 4, height: 20, backgroundColor: "#fff", position: "absolute" }} />
          </div>

          {/* Input Field Shape */}
          <div
            style={{
              flex: 1,
              height: 100,
              backgroundColor: "#f4f5f7",
              borderRadius: 50,
              display: "flex",
              flexDirection: "row",
              alignItems: "center",
              padding: "0 40px",
              marginRight: 30,
            }}
          >
            <span
              style={{
                fontSize: 38,
                color: "#191919",
                whiteSpace: "nowrap",
                overflow: "hidden",
                display: "flex",
                alignItems: "center",
              }}
            >
              {inputTextVisible}
              <div
                style={{
                  width: 4,
                  height: 46,
                  backgroundColor: themeColor,
                  marginLeft: 4,
                  opacity: cursorOpacity,
                  borderRadius: 2,
                  transition: "none",
                }}
              />
            </span>
            {frame < typingStart && (
              <span
                style={{
                  fontSize: 38,
                  color: "#a0a0a0",
                  position: "absolute",
                  left: 160,
                  pointerEvents: "none",
                }}
              >
                Write a message...
              </span>
            )}
          </div>

          {/* Send Button */}
          <div
            style={{
              opacity: finalSendOpacity,
              transform: `scale(${tapScale})`,
              transition: "none",
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
              height: 100,
              padding: "0 10px",
            }}
          >
            <span
              style={{
                fontSize: 40,
                color: themeColor,
                fontWeight: 600,
              }}
            >
              Send
            </span>
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default LinkedInChat;